def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    frames = []

    # Find connected components and keep those containing a complete
    # rectangular border.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = set()
            while stack:
                y, x = stack.pop()
                comp.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in comp)
            r1 = max(y for y, x in comp)
            c0 = min(x for y, x in comp)
            c1 = max(x for y, x in comp)
            border = {
                (y, x)
                for y in range(r0, r1 + 1)
                for x in range(c0, c1 + 1)
                if y in (r0, r1) or x in (c0, c1)
            }
            if border <= comp and r1 - r0 >= 2 and c1 - c0 >= 2:
                frames.append((color, r0, r1, c0, c1, comp))

    # Record the trimmed interior pattern of each frame that has one.
    donors = []
    for color, r0, r1, c0, c1, comp in frames:
        cells = [
            (y, x)
            for y in range(r0 + 1, r1)
            for x in range(c0 + 1, c1)
            if grid[y][x] == color
        ]
        if cells:
            pr0 = min(y for y, x in cells)
            pr1 = max(y for y, x in cells)
            pc0 = min(x for y, x in cells)
            pc1 = max(x for y, x in cells)
            pattern = [
                [grid[y][x] == color for x in range(pc0, pc1 + 1)]
                for y in range(pr0, pr1 + 1)
            ]
            donors.append((color, pattern))

    for color, r0, r1, c0, c1, comp in frames:
        ih, iw = r1 - r0 - 1, c1 - c0 - 1
        interior_has_pattern = any(
            grid[y][x] == color
            for y in range(r0 + 1, r1)
            for x in range(c0 + 1, c1)
        )
        if interior_has_pattern:
            continue

        matches = [
            pattern for donor_color, pattern in donors
            if donor_color != color and len(pattern) == ih and len(pattern[0]) == iw
        ]
        if matches:
            pattern = matches[0]
            for i in range(ih):
                for j in range(iw):
                    if pattern[i][j]:
                        out[r0 + 1 + i][c0 + 1 + j] = color
        else:
            # An empty frame with no matching pattern is removed.
            for y, x in comp:
                out[y][x] = 0

    return out
